"use strict";(self.webpackChunk_223_calendar=self.webpackChunk_223_calendar||[]).push([[651],{388:function(n,t){t.default={meta:{tagline:"Hôm đó các con có ở với tôi không?",description:"Công cụ nhỏ gọn, chạy hoàn toàn trên trình duyệt, dành cho lịch nuôi con 2-2-3. Chọn hai ngày bạn đã đón con trong tuần này, chọn một ngày bất kỳ, và bạn sẽ biết hôm đó các con ở với ai."},nav:{check:"Kiểm tra một ngày",how:"Cách hoạt động",alephvoid:"Aleph Void",language:"Ngôn ngữ"},hero:{badge:"Lịch nuôi con 2-2-3",title:"Các con có ở với tôi {accent}",titleAccent:"hôm đó không?",subtitle:"Vòng luân phiên 2-2-3 là một chu kỳ 14 ngày, nên bất kỳ ngày nào cách hơn một tuần đều thành chuyện đoán mò. Hãy cho biết hai ngày trong tuần này là của bạn, chọn một ngày, rồi nhận câu trả lời.",claim:"{strong} Không tài khoản, không máy chủ, không dữ liệu nào rời khỏi trình duyệt — mở được cả trên máy bay.",claimStrong:"Chạy hoàn toàn trên trình duyệt."},step1:{num:"Bước 1",title:"Tuần này bạn đón các con vào hai ngày nào trong tuần?",note:"“Tuần này” là tuần bắt đầu từ {date}. Chọn cặp ngày đúng — phần còn lại của chu kỳ sẽ được tính tự động.",group:"Hai ngày trong tuần bạn đón các con tuần này"},choice:{pair:"{a} và {b}",montueSub:"Cuối tuần này cũng là của bạn — từ thứ Sáu đến sáng thứ Hai.",wedthuSub:"Cuối tuần này thuộc về mẹ các con — từ thứ Sáu đến sáng thứ Hai."},step2:{num:"Bước 2",title:"Chọn ngày bạn muốn kiểm tra",dateLabel:"Ngày cần kiểm tra",check:"Kiểm tra ngày này",jump:"Nhảy tới",today:"Hôm nay",tomorrow:"Ngày mai",plusWeek:"+1 tuần",plus30:"+30 ngày",plus90:"+90 ngày"},error:{pattern:"Hãy chọn một trong hai phương án ở bước 1 trước.",date:"Hãy chọn một ngày để kiểm tra."},result:{yes:"Có",no:"Không",withYou:"Đêm đó các con ở với bạn.",withThem:"Đêm đó các con ở với mẹ.",stretchLabel:"Đợt này",cycleLabel:"Vị trí trong chu kỳ",nextLabel:"Lần bàn giao tới",range:"{from} → {to}",stretchYou:"Ở với bạn: {span} ({nights})",stretchThem:"Ở với mẹ: {span} ({nights})",nights:{other:"{n} đêm"},cycle:"Ngày {day}/14 — tuần {week}, {weekday}",nextToThem:"Sáng {date} — các con về với mẹ",nextToYou:"Sáng {date} — các con về với bạn",prevMonth:"Tháng trước",nextMonth:"Tháng sau",legendYou:"Ở với bạn",legendThem:"Ở với mẹ",legendTarget:"Ngày đã kiểm tra",cellYou:"{date} — ở với bạn",cellThem:"{date} — ở với mẹ"},share:{button:"Sao chép liên kết",native:"Chia sẻ",copied:"Đã sao chép liên kết.",label:"Liên kết chia sẻ",hint:"Liên kết mang theo lịch này và ngày này, nên ai mở cũng thấy đúng câu trả lời đó.",opened:"Mở từ một liên kết được chia sẻ — lịch bên dưới đến từ liên kết đó, không phải lựa chọn bạn đã lưu."},how:{eyebrow:"Quy luật",title:"Một chu kỳ, mười bốn ngày",lead:"Mỗi người đều nhận đúng bảy ngày trong mười bốn ngày. Tuần một là hình phản chiếu của tuần hai — vì vậy chỉ nhìn một tuần thì không bao giờ đủ.",week1:"Tuần 1 — bạn đón {pair}",week2:"Tuần 2 — mọi thứ đảo lại",you:"Bạn",mother:"Mẹ",note1Title:"Ngày được tính theo đêm ngủ lại",note1Body:"Một ngày thuộc về người có các con ngủ lại đêm đó. Cuối tuần từ thứ Sáu đến Chủ nhật kết thúc khi trả con vào sáng thứ Hai, nên thứ Hai đó được tính cho người mở đầu đợt tiếp theo.",note2Title:"Tuần bắt đầu từ thứ Hai",note2Body:"Bước 1 hỏi về tuần thứ Hai–Chủ nhật mà bạn đang ở trong đó. Nếu hôm nay là Chủ nhật, thì đó vẫn là tuần đã bắt đầu sáu ngày trước.",note3Title:"Không tính ngày lễ",note3Body:"Đây chỉ là vòng luân phiên thuần túy. Việc đổi ngày lễ, các tuần nghỉ và những lần hoán đổi riêng lẻ trong thỏa thuận nuôi con của bạn luôn được ưu tiên hơn những gì hiển thị ở đây."},footer:{home:"Trang chủ",link:"Aleph Void LLC",copy:"Được tạo bởi {link}. © {year} {brand}. Chạy hoàn toàn trên trình duyệt của bạn; không có gì được tải lên. Đây không phải tư vấn pháp lý — thỏa thuận nuôi con của bạn mới là căn cứ."}}}}]);